/**
 * main.js — self-contained Three.js anatomical liver scene.
 *
 * No backend. Assets consumed (all generated by tools/, all with provenance):
 *   assets/liver.glb              anatomical surfaces + baked liver coordinates
 *   assets/liver_vessels.json     four tubular trees (Murray radii)
 *   assets/liver_flow.json        flow paths with real v = Q/A per sample
 *   assets/liver_model.json       haemodynamics + respiration contract
 *   assets/liver_expression.json  measured single-cell zonal expression
 *   assets/couinaud.json          segment planes and volumes
 *
 * Public API (also used by the automated probe):
 *   const api = await createLiverScene({ container, assetBase, view })
 *   api.setView('organ'|'lobule'), api.setPlaybackRate(x), api.setGene('CYP1A2'),
 *   api.setParticleDensity(f), api.dispose()
 *   window.__liver3d  diagnostics for the headless benchmark
 */

import * as THREE from 'three';
import { GLTFLoader } from '../vendor/jsm/loaders/GLTFLoader.js';
import { OrbitControls } from '../vendor/jsm/controls/OrbitControls.js';
import { RoomEnvironment } from '../vendor/jsm/environments/RoomEnvironment.js';

import { RespirationField } from './respiration.js';
import {
  makeParenchymaMaterial, makeVesselMaterial, makeGallbladderMaterial, SEGMENT_COLORS
} from './materials.js';
import { buildVesselMesh, TREE_COLOR } from './vessels.js';
import { FlowSystem } from './flow.js';
import { buildLobule, MAGNIFICATION } from './lobule.js';
import { HUD, NARROW_PX } from './hud.js';

const LOBULE_OFFSET = new THREE.Vector3(0, -900, 0);

export async function createLiverScene (opts = {}) {
  const container = opts.container || document.body;
  const base = opts.assetBase || './assets/';
  const stage = (s) => { window.__liver3dStage = s; };

  stage('renderer:begin');
  const renderer = new THREE.WebGLRenderer({
    antialias: true, powerPreference: 'high-performance', alpha: false
  });
  const narrow0 = container.clientWidth < NARROW_PX;
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, narrow0 ? 1.75 : 2));
  renderer.setSize(container.clientWidth, container.clientHeight);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.05;
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  container.appendChild(renderer.domElement);

  stage('renderer:ok');
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x070a10);

  const pmrem = new THREE.PMREMGenerator(renderer);
  scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
  scene.environmentIntensity = 0.6;
  stage('pmrem:ok');

  const camera = new THREE.PerspectiveCamera(
    40, container.clientWidth / container.clientHeight, 1, 6000);
  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.07;
  controls.minDistance = 40;
  controls.maxDistance = 1600;

  const key = new THREE.DirectionalLight(0xfff1e8, 2.3); key.position.set(1, 1.0, 0.9);
  const fill = new THREE.DirectionalLight(0x9fc4ff, 0.6); fill.position.set(-1.1, 0.25, -0.5);
  const rim = new THREE.DirectionalLight(0xffcfc0, 1.0); rim.position.set(-0.3, -0.8, -1.0);
  scene.add(key, fill, rim, new THREE.AmbientLight(0x30405a, 0.65));

  // ------------------------------------------------------------------ assets
  stage('fetch:begin');
  const [vessels, flowSpec, model, expr, couinaud] = await Promise.all([
    fetch(base + 'liver_vessels.json').then(r => r.json()),
    fetch(base + 'liver_flow.json').then(r => r.json()),
    fetch(base + 'liver_model.json').then(r => r.json()),
    fetch(base + 'liver_expression.json').then(r => r.json()),
    fetch(base + 'couinaud.json').then(r => r.json())
  ]);
  stage('fetch:ok');

  const gltf = await new GLTFLoader().loadAsync(base + 'liver.glb');
  stage('glb:ok');

  // ------------------------------------------------------------ organ group
  const organ = new THREE.Group();
  scene.add(organ);
  const liverBody = new THREE.Group();     // everything that breathes
  organ.add(liverBody);

  const parenMat = makeParenchymaMaterial();
  const gbMat = makeGallbladderMaterial();
  const vesselMats = {
    portal_vein: makeVesselMaterial(TREE_COLOR.portal_vein),
    hepatic_vein: makeVesselMaterial(TREE_COLOR.hepatic_vein),
    hepatic_artery: makeVesselMaterial(TREE_COLOR.hepatic_artery),
    bile_duct: makeVesselMaterial(TREE_COLOR.bile_duct),
    ivc: makeVesselMaterial(0x6b7e99, { opacity: 0.92 })
  };
  const allMats = [parenMat, gbMat, ...Object.values(vesselMats)];

  let triangles = 0;
  const parts = {};
  gltf.scene.traverse((o) => {
    if (!o.isMesh) return;
    const g = o.geometry;
    if (!g.getAttribute('_field0')) {
      console.warn(`[liver3d] mesh "${o.name}" lacks _field0; skipped`);
      return;
    }
    let mat = parenMat;
    if (o.name === 'gallbladder') mat = gbMat;
    else if (o.name === 'ivc') mat = vesselMats.ivc;
    else if (o.name === 'portal_vein') mat = vesselMats.portal_vein;
    const mesh = new THREE.Mesh(g, mat);
    mesh.name = o.name;
    mesh.frustumCulled = false;
    liverBody.add(mesh);
    parts[o.name] = mesh;
    triangles += (g.index ? g.index.count : g.getAttribute('position').count) / 3;
  });
  stage('surfaces:ok');

  // ------------------------------------------------------------ vessel trees
  const treeMeshes = {};
  const treeStats = {};
  for (const tree of vessels.trees) {
    const built = buildVesselMesh(tree, {});
    const mesh = new THREE.Mesh(built.geometry, vesselMats[tree.name]);
    mesh.name = 'tree_' + tree.name;
    mesh.frustumCulled = false;
    liverBody.add(mesh);
    treeMeshes[tree.name] = mesh;
    treeStats[tree.name] = built.stats;
    triangles += built.stats.triangles;
  }
  stage('vessels:ok');

  // ------------------------------------------------------------------- flow
  const narrowNow = () => container.clientWidth < NARROW_PX;
  const basePPP = opts.particlesPerPath || (narrowNow() ? 140 : 320);
  const flow = new FlowSystem(flowSpec, basePPP);
  flow.setPixelRatio(renderer.getPixelRatio());
  liverBody.add(flow.points);
  stage('flow:ok');

  // ------------------------------------------------------------- respiration
  const cranial = new THREE.Vector3(0, 1, 0);
  const pivot = new THREE.Vector3().fromArray(vessels.hepatocaval_confluence);
  const resp = new RespirationField(model.respiration, cranial, pivot,
                                   { excursionCm: opts.excursionCm });
  stage('respiration:ok');

  // ----------------------------------------------------------------- lobule
  const lob = buildLobule(model);
  lob.group.position.copy(LOBULE_OFFSET);
  scene.add(lob.group);
  const lobFlow = new FlowSystem(lob.flowSpec, narrowNow() ? 40 : 90);
  lobFlow.setPixelRatio(renderer.getPixelRatio());
  lobFlow.setParticleScale(1.5);
  lob.group.add(lobFlow.points);
  let lobTriangles = 0;
  lob.group.traverse(o => {
    if (o.isMesh && o.geometry.index) lobTriangles += o.geometry.index.count / 3;
    else if (o.isMesh) lobTriangles += o.geometry.getAttribute('position').count / 3;
  });
  // The arterial and biliary trees are portal-triad companions of the portal
  // tree: anatomically correct, but showing all four at once makes an
  // unreadable thicket. They start hidden and the page exposes the toggles.
  if (treeMeshes.hepatic_artery) treeMeshes.hepatic_artery.visible = false;
  if (treeMeshes.bile_duct) treeMeshes.bile_duct.visible = false;
  flow.setTreeEnabled('hepatic_artery', false);
  flow.setTreeEnabled('bile_duct', false);

  stage('lobule:ok');

  // ---------------------------------------------------------- zonal binding
  // The zonal gradient is NOT uniform across genes. Each gene carries its own
  // measured central/periportal ratio and the ramp direction follows it.
  const ZONE_ORDER = ['periportal', 'midzonal', 'pericentral'];
  const zonal = model.zonal_expression;
  const geneNames = Object.keys(zonal);
  let gene = opts.gene && zonal[opts.gene] ? opts.gene : 'CYP1A2';

  function applyGene (name) {
    if (!zonal[name]) return;
    gene = name;
    const e = zonal[name].expr;                      // [periportal, mid, central]
    const ratio = zonal[name].ratio_central_over_periportal;
    for (const m of allMats) {
      const u = m.userData.uniforms;
      if (u && u.uZoneRatio) u.uZoneRatio.value = ratio;
    }
    const lu = lob.plateMat.userData.uniforms;
    lu.uZoneExpr.value.set(e[0], e[1], e[2]);
    lu.uZoneRatio.value = ratio;
  }
  applyGene(gene);

  // ------------------------------------------------------------------- view
  let view = opts.view || 'organ';
  // Box3.expandByObject only refreshes the object's OWN world matrix, not its
  // ancestors', so the lobule group's offset would be ignored and the camera
  // would frame empty space. Flush the whole graph first.
  scene.updateMatrixWorld(true);
  // Framing must come from the SURFACES only: the particle Points carry a
  // deliberately huge bounding sphere (so they are never frustum-culled), and
  // including them in the box pushes the camera ~10x too far away.
  const organBox = new THREE.Box3();
  for (const name of ['parenchyma', 'gallbladder', 'ivc']) {
    if (parts[name]) organBox.expandByObject(parts[name]);
  }
  const organCentre = organBox.getCenter(new THREE.Vector3());
  const organRadius = organBox.getSize(new THREE.Vector3()).length() * 0.5;
  const lobBox = new THREE.Box3();
  lob.group.traverse(o => {
    if (o.isMesh) lobBox.expandByObject(o);
  });
  const lobCentre = lobBox.getCenter(new THREE.Vector3());
  const lobRadius = lobBox.getSize(new THREE.Vector3()).length() * 0.5;

  function frameView (v, instant = true) {
    const centre = v === 'lobule' ? lobCentre : organCentre;
    const radius = v === 'lobule' ? lobRadius : organRadius;
    const fov = THREE.MathUtils.degToRad(camera.fov);
    const aspect = Math.max(camera.aspect, 0.35);
    // fit by the limiting dimension so a tall phone viewport does not crop
    const dist = radius / Math.sin(Math.min(fov / 2, Math.atan(Math.tan(fov / 2) * aspect)));
    // The lobule is a tall prism: the bounding-sphere fit leaves much less
    // apparent margin than it does for the compact organ, so each view carries
    // its own margin factor instead of one shared constant.
    const margin = v === 'lobule' ? 1.18 : 0.84;
    controls.target.copy(centre);
    camera.position.copy(centre).add(
      new THREE.Vector3(0.55, 0.30, 1.0).normalize().multiplyScalar(dist * margin));
    camera.near = radius * 0.01; camera.far = radius * 60;
    camera.updateProjectionMatrix();
    controls.update();
  }

  const LIGHT_BASE = { key: 2.3, fill: 0.6, rim: 1.0, env: 0.6, exposure: 1.05 };
  function setView (v) {
    view = v;
    lob.group.visible = (v === 'lobule');
    organ.visible = (v === 'organ');
    // The lobule's hepatocyte plates are a pale tissue; under the organ-view key
    // light they clip to cream and the measured zonal ramp becomes invisible.
    const f = v === 'lobule' ? 0.42 : 1.0;
    key.intensity = LIGHT_BASE.key * f;
    fill.intensity = LIGHT_BASE.fill * f;
    rim.intensity = LIGHT_BASE.rim * f;
    scene.environmentIntensity = LIGHT_BASE.env * (v === 'lobule' ? 0.45 : 1.0);
    renderer.toneMappingExposure = LIGHT_BASE.exposure * (v === 'lobule' ? 0.92 : 1.0);
    frameView(v);
  }

  // --------------------------------------------------------------------- HUD
  const hudCanvas = document.createElement('canvas');
  hudCanvas.style.cssText = 'position:absolute;inset:0;pointer-events:none;z-index:5';
  container.appendChild(hudCanvas);
  const hud = new HUD(hudCanvas);

  let densityUser = 1.0;
  function applyDensity () {
    // narrow screens get fewer particles AND a smaller sprite
    const narrow = narrowNow();
    const f = densityUser * (narrow ? 0.45 : 1.0);
    flow.setDensity(f);
    lobFlow.setDensity(f);
    flow.setParticleScale(narrow ? 0.8 : 1.0);
    lobFlow.setParticleScale(narrow ? 1.15 : 1.5);
  }

  function resize () {
    const w = container.clientWidth; const h = container.clientHeight;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, w < NARROW_PX ? 1.75 : 2));
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    hud.resize(w, h, renderer.getPixelRatio());
    flow.setPixelRatio(renderer.getPixelRatio());
    lobFlow.setPixelRatio(renderer.getPixelRatio());
    applyDensity();
    frameView(view);
  }
  window.addEventListener('resize', resize);
  resize();
  setView(view);
  applyDensity();

  // ------------------------------------------------------------------- clock
  let simMs = 0;
  let playbackRate = 1.0;
  let running = true;
  let lastNow = performance.now();
  const frameTimes = [];
  let frameCount = 0;

  const flowByTree = {};
  for (const t of Object.keys(TREE_COLOR)) {
    const ps = flowSpec.paths.filter(p => p.tree === t);
    const v = ps.length ? ps.reduce((s, p) => s + p.v_mm_s[0], 0) / ps.length : 0;
    flowByTree[t] = v / 10.0;         // cm/s at the proximal sample
  }

  const diag = {
    triangles,
    lobuleTriangles: lobTriangles,
    particles: flow.nParticles,
    lobuleParticles: lobFlow.nParticles,
    trees: treeStats,
    flow: flow.diagnostics(),
    lobule: lob.info,
    respiration: resp.describe(),
    couinaud: couinaud.segment_volume_mL,
    genes: geneNames,
    zonalRatios: Object.fromEntries(geneNames.map(
      g => [g, zonal[g].ratio_central_over_periportal])),
    expressionCells: expr.n_cells_used ? expr.n_cells_used.slice(0, 3) : null,
    ready: false
  };

  const colOf = (hex) => '#' + hex.toString(16).padStart(6, '0');

  function frame (now) {
    if (!running) return;
    const wallDt = Math.min(now - lastNow, 100);
    lastNow = now;
    frameTimes.push(wallDt);
    if (frameTimes.length > 900) frameTimes.shift();
    frameCount++;
    const dtSim = wallDt * playbackRate;
    simMs += dtSim;

    const m = resp.update(simMs);
    liverBody.matrixAutoUpdate = false;
    liverBody.matrix.copy(m);
    liverBody.matrixWorldNeedsUpdate = true;

    if (view === 'organ') flow.update(dtSim, 1.0);
    else lobFlow.update(dtSim, 1.0);

    controls.update();
    renderer.render(scene, camera);

    hud.tickFps(now);
    hud.draw({
      fps: hud.fps,
      triangles: view === 'lobule' ? lobTriangles : triangles,
      particlesDrawn: view === 'lobule'
        ? (lobFlow.drawn || lobFlow.nParticles) : (flow.drawn || flow.nParticles),
      view,
      magnification: MAGNIFICATION,
      respiration: {
        phase01: resp.phase01,
        breaths_per_min: resp.breathsPerMin,
        displacement_mm: resp.displacementMm
      },
      flow: view === 'lobule'
        ? {
            portal: { text: 'sinusoid ' + lob.info.sinusoid_velocity_mm_s.toFixed(3) + ' mm/s',
                      color: colOf(TREE_COLOR.portal_vein) },
            hepatic: { text: 'canaliculus ' + lob.info.bile_velocity_mm_s + ' mm/s',
                       color: colOf(TREE_COLOR.bile_duct) },
            arterial: { text: 'inward -> central vein',
                        color: colOf(TREE_COLOR.hepatic_artery) },
            bile: { text: 'bile shown ' + lob.info.bile_display_gain + 'x',
                    color: colOf(TREE_COLOR.bile_duct) }
          }
        : {
            portal: { text: flowByTree.portal_vein.toFixed(1) + ' cm/s',
                      color: colOf(TREE_COLOR.portal_vein) },
            arterial: { text: flowByTree.hepatic_artery.toFixed(1) + ' cm/s',
                        color: colOf(TREE_COLOR.hepatic_artery) },
            hepatic: { text: flowByTree.hepatic_vein.toFixed(1) + ' cm/s',
                       color: colOf(TREE_COLOR.hepatic_vein) },
            bile: { text: flowByTree.bile_duct.toFixed(2) + ' cm/s ↩',
                    color: colOf(TREE_COLOR.bile_duct) }
          },
      note: view === 'lobule'
        ? `zonal tint: ${gene} central/periportal ${zonal[gene].ratio_central_over_periportal.toFixed(2)}x (measured)`
        : 'TotalSegmentator v2 CC-BY-4.0 · s0236'
    });

    requestAnimationFrame(frame);
  }
  stage('loop:start');
  requestAnimationFrame(frame);
  diag.ready = true;
  stage('ready');

  const api = {
    renderer, scene, camera, controls, hud, organ, liverBody, lobule: lob.group,
    flow, lobFlow, resp, parts, treeMeshes, diag, model, vessels, couinaud,
    get simMs () { return simMs; },
    get view () { return view; },
    get gene () { return gene; },
    setView,
    setGene: applyGene,
    genes: geneNames,
    setPlaybackRate (x) { playbackRate = x; },
    setParticleDensity (f) { densityUser = f; applyDensity(); },
    setOverlay (which, on) {
      const v = on ? 1.0 : 0.0;
      for (const m of allMats) {
        const u = m.userData.uniforms;
        if (!u) continue;
        if (which === 'segments') u.uSegmentMix.value = v;
        if (which === 'zones') u.uZoneMix.value = v;
        if (which === 'ligament') u.uLigament.value = on ? 1.0 : 0.0;
      }
    },
    setPartVisible (name, on) {
      if (parts[name]) parts[name].visible = on;
      if (treeMeshes[name]) treeMeshes[name].visible = on;
    },
    setClip (normal, offset, on) {
      const p = new THREE.Vector4(normal.x, normal.y, normal.z, offset);
      for (const m of allMats) {
        const u = m.userData.uniforms;
        if (!u || !u.uClipPlane) continue;
        u.uClipPlane.value.copy(p);
        u.uClipOn.value = on ? 1.0 : 0.0;
      }
      flow.material.uniforms.uClipPlane.value.copy(p);
      flow.material.uniforms.uClipOn.value = on ? 1.0 : 0.0;
    },
    frameStats () {
      const a = frameTimes.slice().sort((x, y) => x - y);
      const mean = a.reduce((s, v) => s + v, 0) / Math.max(a.length, 1);
      return {
        frames: frameCount, meanFrameMs: mean,
        medianFrameMs: a.length ? a[Math.floor(a.length / 2)] : NaN,
        p95FrameMs: a.length ? a[Math.floor(a.length * 0.95)] : NaN,
        fpsMean: 1000 / mean,
        fpsMedian: a.length ? 1000 / a[Math.floor(a.length / 2)] : NaN
      };
    },
    resetFrameStats () { frameTimes.length = 0; frameCount = 0; },
    hudOverflow () { return hud.overflow(); },
    dispose () {
      running = false;
      window.removeEventListener('resize', resize);
      renderer.dispose();
    }
  };

  window.__liver3d = api;
  return api;
}

export { SEGMENT_COLORS };
